import{_ as l,H as i,f as p,i as a}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"17 | 天下武功唯快不破？高频与盘口","description":"","frontmatter":{},"headers":[{"level":2,"title":"K 线背后的真相：订单簿","slug":"k-线背后的真相-订单簿","link":"#k-线背后的真相-订单簿","children":[]},{"level":2,"title":"看不见的敌人：冰山订单","slug":"看不见的敌人-冰山订单","link":"#看不见的敌人-冰山订单","children":[]},{"level":2,"title":"诱骗的艺术：幌骗（Spoofing）","slug":"诱骗的艺术-幌骗-spoofing","link":"#诱骗的艺术-幌骗-spoofing","children":[]},{"level":2,"title":"赚差价的人：做市商与多空失衡","slug":"赚差价的人-做市商与多空失衡","link":"#赚差价的人-做市商与多空失衡","children":[]},{"level":2,"title":"成交量的微观结构：VWAP 算法","slug":"成交量的微观结构-vwap-算法","link":"#成交量的微观结构-vwap-算法","children":[]},{"level":2,"title":"AI 量化策略建议","slug":"ai-量化策略建议","link":"#ai-量化策略建议","children":[]},{"level":2,"title":"本讲金句弹幕","slug":"本讲金句弹幕","link":"#本讲金句弹幕","children":[]},{"level":2,"title":"课后思考","slug":"课后思考","link":"#课后思考","children":[]},{"level":2,"title":"下节预告","slug":"下节预告","link":"#下节预告","children":[]}],"relativePath":"人人都用得上的AI量化思维课/17｜天下武功唯快不破？高频与盘口.md","filePath":"人人都用得上的AI量化思维课/17｜天下武功唯快不破？高频与盘口.md","lastUpdated":1795541548000}'),t={name:"人人都用得上的AI量化思维课/17｜天下武功唯快不破？高频与盘口.md"};function n(o,e,r,s,h,E){return i(),p("div",null,[...e[0]||(e[0]=[a('<h1 id="_17-天下武功唯快不破-高频与盘口" tabindex="-1">17 | 天下武功唯快不破？高频与盘口 <a class="header-anchor" href="#_17-天下武功唯快不破-高频与盘口" aria-label="Permalink to &quot;17 | 天下武功唯快不破？高频与盘口&quot;">​</a></h1><p>你好，我是陈旸。</p><p>你看过电影《蜂鸟计划》吗？讲的是两个交易员为了比别人快 16 毫秒接收到行情数据，不惜斥资几亿美元，从堪萨斯到新泽西拉了一条直线光缆，甚至要把山打穿。为什么这 0.016 秒值几个亿？因为在量化交易的微观世界里，时间就是套利空间。</p><p>如果我比你早 1 毫秒知道苹果的股价在纽约涨了，我就能在你在芝加哥反应过来之前，先把芝加哥的便宜筹码扫光，然后高价卖给你。这叫延迟套利。但是，作为坐在家里用着普通宽带、跑着 QMT 的普通量化投资者，我们必须面对一个残酷的现实：在拼速度这条赛道上，我们永远赢不了那些把服务器架在交易所机房里的顶级机构。</p><p>那为什么我们还要学这一讲？因为我们学的不是如何跑得快（去进攻），而是如何看清跑得快的人留下的脚印（去防御）。</p><p>高频交易者在盘口留下的痕迹，往往暴露了市场的真实意图。AI 量化思维的精髓，就是利用这些微观数据，来辅助我们的宏观决策——不是为了去捡芝麻，而是为了防止被收割和降低交易成本。</p><h2 id="k-线背后的真相-订单簿" tabindex="-1">K 线背后的真相：订单簿 <a class="header-anchor" href="#k-线背后的真相-订单簿" aria-label="Permalink to &quot;K 线背后的真相：订单簿&quot;">​</a></h2><p>我们平时看的 K 线图，其实是被压缩过的数据。一根 1 分钟的 K 线，只告诉你这 1 分钟的开盘、收盘、最高、最低价。它丢失了最重要的信息：在这 1 分钟里，多空双方是怎么打架的？要看清这个过程，我们需要打开 Level 2 数据，也就是订单簿（Order Book）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/17/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/17/1.png" alt=""></a></p><p>想象你在逛菜市场：</p><ul><li><p>K 线图只是告诉你：刚才成交了一斤白菜，价格是 2 块钱。</p></li><li><p>订单簿则是告诉你：</p></li><li><p>摊主 A 挂单：2.1 元卖 100 斤（卖一）</p></li><li><p>摊主 B 挂单：2.2 元卖 500 斤（卖二）</p></li><li><p>顾客 C 喊价：1.9 元买 50 斤（买一）</p></li><li><p>顾客 D 喊价：1.8 元买 2000 斤（买二）</p></li></ul><p>这就是盘口。它展示了市场的深度和流动性。</p><p>想象一下，有这样一张订单簿深度图。虽然当前价格是 2.0 元，但在下方 1.8 元的位置，有一根极长的横条（2000 斤买单）。</p><p>量化视角的洞察：</p><p>请注意上面的数据。虽然现在的价格是 2 块钱，但下方的买二（1.8 元）挂了 2000 斤的大单。这在量化里叫厚尾或支撑墙。这意味着，虽然现在价格在跌，但下方有巨量的承接盘。AI模型读取到这个 Order Book 形态后，会判断：短期下跌空间有限，可以尝试低吸。这就是看盘口和看 K 线的区别——K 线看的是历史，盘口看的是意图。</p><h2 id="看不见的敌人-冰山订单" tabindex="-1">看不见的敌人：冰山订单 <a class="header-anchor" href="#看不见的敌人-冰山订单" aria-label="Permalink to &quot;看不见的敌人：冰山订单&quot;">​</a></h2><p>在微观世界里，最大的谎言就是：眼见为实。你在盘口上看到的卖一只有 10 手（1000 股），你以为抛压很轻，于是你冲进去买。结果你刚吃掉这 10 手，瞬间又冒出来 10 手。你再吃，它再冒。</p><p>就像打地鼠一样，永远打不完。</p><p>等你买了 1000 手发现还没买完时，你慌了。这就是冰山订单。</p><p>想象一座冰山，水面上只露出一角（显示 10 手），水面下藏着巨大的冰体（库存 100 万手）。拆单算法就像一个水泵，不断把水下的冰推到水面上。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/17/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/17/2.png" alt=""></a></p><p>原理：大机构如果要卖出 100 万股，直接挂在盘口上，会把散户吓跑，导致股价暴跌，自己卖不上好价钱。于是，他们使用拆单算法。设定一个规则：“只显示 10 手。每当这 10 手被吃掉，立刻从库存里自动补充 10 手，直到卖完为止。”</p><p>AI 如何识别冰山？</p><p>人眼很难发现，因为刷新速度太快。但 AI 可以。我们在 QMT 里写一个简单的逻辑：</p><ol><li><p>监控某一个价位（比如 10.00 元）。</p></li><li><p>计算在该价位累计成交的数量。</p></li><li><p>如果 累计成交量 &gt;&gt; 盘口显示的挂单量 （比如显示 100 股，却成交了 1 万股，价格还没变）。</p></li><li><p>报警：发现冰山卖单！</p></li></ol><p>应对策略：请注意，我们识别冰山不是为了去套利，而是为了避险。一旦 AI 识别出上方有冰山卖单，千万别买。哪怕 K 线形态再好，也要等这座冰山被融化之后再进场。</p><h2 id="诱骗的艺术-幌骗-spoofing" tabindex="-1">诱骗的艺术：幌骗（Spoofing） <a class="header-anchor" href="#诱骗的艺术-幌骗-spoofing" aria-label="Permalink to &quot;诱骗的艺术：幌骗（Spoofing）&quot;">​</a></h2><p>如果说冰山订单是想卖装作不想卖，那么幌骗就是不想买装作想买。这是一种非法的，但在高频世界里屡禁不止的操纵手段。</p><p>剧本如下：</p><ol><li><p>设局：高频交易者想把股票以 10.1 元卖给你。但他觉得现在买气不足。</p></li><li><p>诱饵：他在买二、买三的位置（比如 10.0 元），瞬间挂出巨额买单（比如 10 万手）。</p></li><li><p>上钩：你看到下方有巨大的托单，觉得支撑很强，主力在护盘。于是你放心地以 10.1 元买入。</p></li><li><p>撤单：就在你成交的那一微秒，高频交易者瞬间撤销了下方那 10 万手买单。</p></li><li><p>收割：支撑瞬间消失，股价自由落体。你被套在了高位。</p></li></ol><p>这就是挂假单。他们根本没想成交，他们只是为了制造流动性充足的假象，诱导你做出错误的决策。</p><p>AI 如何识别幌骗？</p><p>我们需要计算一个核心指标：订单撤销率。正常交易者的撤单率可能在 10% 左右。而幌骗策略的撤单率往往高达 95% 以上。如果你发现盘口上经常出现大单，但每次快要成交时就消失了，这绝对不是主力在逗你玩，这是机器在钓鱼。</p><p>AI 的指令： 忽略这些虚假的深度，不要把它们计入支撑位。</p><h2 id="赚差价的人-做市商与多空失衡" tabindex="-1">赚差价的人：做市商与多空失衡 <a class="header-anchor" href="#赚差价的人-做市商与多空失衡" aria-label="Permalink to &quot;赚差价的人：做市商与多空失衡&quot;">​</a></h2><p>除了这些尔虞我诈，高频交易还有一个正经的流派——做市。做市商是市场的润滑剂。他们通过挂出买单和卖单，赚取买卖价差。但他们面临着最大的风险——逆向选择（被知情交易者砸盘）。作为量化交易者，我们不仅要看成交量，还要看多空的实时力量对比。这里我要教大家一个在 CTA 策略里非常实用的指标：买卖深度不平衡（Order Imbalance, OI）。</p><p>公式简单粗暴：</p><p>OI = (买一挂单量 - 卖一挂单量) / (买一挂单量 + 卖一挂单量)</p><p>(注：进阶玩家可以计算前五档或前十档的加权 OI)</p><p>这个指标的值在 -1 到 1 之间：</p><ul><li><p>接近 0：说明买卖势均力敌，市场处于震荡，适合做网格交易。</p></li><li><p>接近 -1：卖单碾压买单，抛压极重。</p></li></ul><p>实战用法与风险提示：当你发现 OI 指标突然从 0 剧烈偏向 -0.8 甚至 -0.9 时，说明盘口瞬间失衡，巨大的抛压涌现。这时候，做市商会立刻撤单逃跑，导致买盘瞬间变空，价格会像瀑布一样下跌。</p><p>你的策略：立刻停止所有的抄底或网格策略。不要接飞刀。</p><p>重要提示：普通交易软件接收到的 Level 2 数据，通常有几十毫秒甚至 3 秒的延迟（快照模式）。千万不要用 OI 指标去写毫秒级的自动打单策略，因为当你看到 OI 失衡时，机构可能已经跑完了。这个指标只能用来辅助你做分钟级的趋势判断：现在是该买，还是该等一等。</p><h2 id="成交量的微观结构-vwap-算法" tabindex="-1">成交量的微观结构：VWAP 算法 <a class="header-anchor" href="#成交量的微观结构-vwap-算法" aria-label="Permalink to &quot;成交量的微观结构：VWAP 算法&quot;">​</a></h2><p>在机构交易中，还有一个非常重要的概念，叫做算法交易。机构为了买入 1 亿股票而不惊动市场，通常会使用 VWAP（成交量加权平均价） 算法，把单子拆碎了，隐藏在市场的自然流动性里。</p><p>AI 量化的实战应用</p><p>我们可以反向工程，去识别主力是否在做 VWAP 吸筹。如果你发现一只股票：</p><ol><li><p>价格波动极小（织布机走势）。</p></li><li><p>但每当成交量放大时，价格总是微微向上跳动。</p></li><li><p>每当成交量缩小时，价格就横住。</p></li></ol><p>这往往是 VWAP 算法在运作的特征。这不仅仅是一个买入信号，更是一颗定心丸。这意味着今天全天都有大资金在托底。只要算法没跑完（通常持续一整天），股价就很难深跌。对于普通投资者，这比单纯的技术指标更具心理支撑价值——你可以放心地持有，与主力共舞。</p><h2 id="ai-量化策略建议" tabindex="-1">AI 量化策略建议 <a class="header-anchor" href="#ai-量化策略建议" aria-label="Permalink to &quot;AI 量化策略建议&quot;">​</a></h2><p>这一讲我们学了很多屠龙术，但作为普通人，我们不要妄想去屠龙。我们学习微观结构，目的是为了防御和省钱。</p><ol><li>定位防御：识别陷阱，而不是火中取栗</li></ol><p>不要试图用家里的电脑去抓幌骗的套利机会，你抢不过机构的。但利用 AI 识别出冰山和幌骗后，你可以选择不交易。</p><ul><li><p>看到冰山压顶，不买。</p></li><li><p>看到毒性订单流（OI 失衡），撤单。</p></li></ul><p>少亏就是赚，这就是盘口数据最大的价值。</p><ol start="2"><li>定位优化：利用 Tick 数据省出利润</li></ol><p>这是普通人唯一能利用盘口直接获利的地方——减少滑点。不要总是挂市价单。利用 QMT 的Tick 数据，看看盘口哪里有支撑墙。</p><ul><li><p>如果你要买，挂在支撑墙的前面一位（插队）。</p></li><li><p>长期下来，每笔交易帮你省 0.1% 的滑点，一年下来就是巨大的超额收益。</p></li></ul><ol start="3"><li>认清现实：硬件的物理鸿沟</li></ol><p>最后再次提醒，量化交易有不同的频段。</p><ul><li><p>高频（毫秒级）：是硬件和光缆的战争，普通人不要涉足。</p></li><li><p>中低频（分钟 / 日线级）：是逻辑和认知的战争，这才是我们的主场。</p></li></ul><p>把盘口数据当作你宏观决策的验证码，而不是发令枪。</p><h2 id="本讲金句弹幕" tabindex="-1">本讲金句弹幕 <a class="header-anchor" href="#本讲金句弹幕" aria-label="Permalink to &quot;本讲金句弹幕&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/17/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/17/3.png" alt=""></a></p><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">​</a></h2><p>打开你常用的交易软件，观察一只正在快速拉升的股票。看它的卖盘，是真的被吃掉了（成交量增加），还是在价格快到的时候自己撤掉了？如果是后者，请思考：这对于你接下来的操作意味着什么？（提示：诱多陷阱，请管住手）。</p><h2 id="下节预告" tabindex="-1">下节预告 <a class="header-anchor" href="#下节预告" aria-label="Permalink to &quot;下节预告&quot;">​</a></h2><p>讲完了 K 线（宏观）和盘口（微观），我们似乎已经把交易所里的数据都挖干净了。但是，如何处理这些海量数据？人类的大脑已经不够用了。下一讲，我们将正式进入第四章：AI 工具（器）。我们将揭开 AI 量化的黑箱，看看它是算命先生，还是概率机器？</p>',69)])])}const c=l(t,[["render",n]]);export{B as __pageData,c as default};
